import path from 'node:path';

/**
 * Resolve a relative path below the workspace root and return the absolute result as a string.
 *
 * @param {string} root - The workspace root path. Can be absolute or relative.
 * @param {string} value - The relative path to resolve against the root.
 * @returns {string} The absolute resolved path.
 * @throws {Error} If the value is an absolute path or escapes the root via `..`.
 */
export function resolveRelative(root, value) {
  // Reject absolute paths outright
  if (path.isAbsolute(value)) {
    throw new Error(`Path escapes the workspace: ${value}`);
  }

  // Resolve the path against the root
  const resolved = path.resolve(root, value);

  // Determine the relative path from root to the resolved path
  const rel = path.relative(root, resolved);

  // If the relative path starts with '..', the resolved path escapes the root
  if (rel.startsWith('..')) {
    throw new Error(`Path escapes the workspace: ${value}`);
  }

  return resolved;
}
